352	impl Eval for ast::FieldAccess<'_> {
353	    type Output = Value;
354	
355	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
356	        let target = self.target().eval(vm)?;
357	        let field = self.field();
358	        access_field(vm, target, field.as_str(), field.span())
359	    }
360	}
361	
362	/// Access a field on a target value.
363	pub(crate) fn access_field(
364	    vm: &mut Vm,
365	    target: Value,
366	    field: &str,
367	    field_span: Span,
368	) -> SourceResult<Value> {
369	    let err = match target.field(field, (&mut vm.engine, field_span)).at(field_span) {
370	        Ok(value) => return Ok(value),
371	        Err(err) => err,
372	    };
373	
374	    // Missing fields may actually be present if they are settable parameters
375	    // on elements accessed with context, e.g. `block.stroke`.
376	    if let Value::Func(func) = &target
377	        && let Some(element) = func.to_element()
378	        && let Some(field_accessor) = element.settable_field_accessor(field)
379	    {
380	        let styles = vm.context.styles().at(field_span)?;
381	        return Ok(field_accessor(styles));
382	    }
383	
384	    Err(err)
385	}
